import re, sys, json, html, urllib.request, urllib.parse, uuid, os

BASE = "http://127.0.0.1:3001"
JAR = {}

def _cookie_header():
    return "; ".join(f"{k}={v}" for k,v in JAR.items())

def _store(resp):
    for h in resp.headers.get_all("Set-Cookie") or []:
        kv = h.split(";")[0]
        if "=" in kv:
            k,v = kv.split("=",1)
            if v in ("", "deleted"): JAR.pop(k, None)
            else: JAR[k]=v

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *a, **k): return None

OP = urllib.request.build_opener(NoRedirect)

def get(path, headers=None):
    req = urllib.request.Request(BASE+path, headers={"Cookie":_cookie_header(), "User-Agent":"qa", **(headers or {})})
    try:
        r = OP.open(req, timeout=60)
    except urllib.error.HTTPError as e:
        r = e
    _store(r)
    body = r.read().decode("utf-8","replace")
    return r.status, dict(r.headers), body

def post_form(path, fields, headers=None):
    data = urllib.parse.urlencode(fields).encode()
    req = urllib.request.Request(BASE+path, data=data, headers={
        "Cookie":_cookie_header(), "Content-Type":"application/x-www-form-urlencoded",
        "User-Agent":"qa", **(headers or {})})
    try:
        r = OP.open(req, timeout=120)
    except urllib.error.HTTPError as e:
        r = e
    _store(r)
    return r.status, dict(r.headers), r.read().decode("utf-8","replace")

def action_fields(page_html, which=1):
    """Extract the no-JS server-action hidden fields for form N."""
    out = {}
    for m in re.finditer(r'<input type="hidden" name="(\$ACTION[^"]*)"(?: value="([^"]*)")?/>', page_html):
        out[html.unescape(m.group(1))] = html.unescape(m.group(2) or "")
    return out

def forms(page_html):
    """Return list of (form_tag, inner_html)."""
    return re.findall(r'(<form[^>]*>)(.*?)</form>', page_html, flags=re.S)

def text(page_html, limit=200, skip=0):
    s = re.sub(r'<script.*?</script>','',page_html,flags=re.S)
    s = re.sub(r'<style.*?</style>','',s,flags=re.S)
    t = html.unescape(re.sub(r'<[^>]+>','\n',s))
    lines=[l.strip() for l in t.split('\n') if l.strip()]
    return "\n".join(lines[skip:skip+limit])
