def post_multipart(path, fields, headers=None):
    boundary = "----qa" + uuid.uuid4().hex
    parts = []
    for k,v in fields.items():
        parts.append(f"--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n")
    parts.append(f"--{boundary}--\r\n")
