  // out. Customers SSH in and run `claude` using their own subscription or API
  // key — no setup on our side, zero token cost to us. Installs run in the
  // background (nohup below) so the VM still reports ready quickly.
  if (addons.claudeCode !== false) {
    setup.push(
      "# --- Nxeon: pre-install Claude Code (Anthropic CLI) ---",
      "(apt-get install -y git curl ca-certificates || dnf install -y git curl ca-certificates || true)",
      "if ! command -v node >/dev/null 2>&1; then " +
        "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
        "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
        "(apt-get install -y nodejs npm || true); fi",
