"use server";

import { db } from "./db";
import { requireUser } from "./auth";
import { SANDBOX } from "./sandbox";
import { revalidatePath } from "next/cache";

/**
 * Sandbox-only instant wallet top-up (no Stripe). Credits play money so the full
 * ordering/billing flow can be exercised on staging without moving real money.
 * Completely inert unless NXEON_SANDBOX=1 — returns an error in production.
 */
export async function sandboxTopUp(cents: number): Promise<{ error?: string; ok?: boolean }> {
  if (!SANDBOX) return { error: "Sandbox top-up is not available here." };
  const user = await requireUser();
  const amount = Math.min(Math.max(Math.round(cents || 0), 100), 100_000); // $1–$1000
  await db.$transaction([
    db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: amount } } }),
    db.walletTransaction.create({
      data: { userId: user.id, amountCents: amount, description: "Sandbox credit (test funds)" },
    }),
  ]);
  revalidatePath("/dashboard/billing");
  return { ok: true };
}
