"use client";

import { useTransition } from "react";
import { useRouter } from "next/navigation";
import { sandboxTopUp } from "@/lib/actions-sandbox";

/** Sandbox-only instant wallet credit buttons (no Stripe). Rendered only when
 *  the page already knows it's in sandbox mode. */
export function SandboxTopUp() {
  const [pending, start] = useTransition();
  const router = useRouter();
  const add = (cents: number) =>
    start(async () => {
      await sandboxTopUp(cents);
      router.refresh();
    });

  return (
    <div className="rounded-2xl border border-amber-400/25 bg-amber-400/[0.06] p-4">
      <p className="text-sm font-semibold text-amber-200">Sandbox test funds</p>
      <p className="mt-1 text-xs text-amber-200/70">
        Instantly credit play money — no Stripe, no real charge. (Sandbox only.)
      </p>
      <div className="mt-3 flex flex-wrap gap-2">
        {[1000, 5000, 25000].map((c) => (
          <button
            key={c}
            disabled={pending}
            onClick={() => add(c)}
            className="btn-secondary py-1.5 text-sm disabled:opacity-50"
          >
            + ${(c / 100).toFixed(0)}
          </button>
        ))}
      </div>
    </div>
  );
}

